generated_pydough:
customers_who_bought_keyboard = customer.WHERE(
    HAS(customer_order.order_item.product.WHERE(product_name == 'keyboard')) == 1
).CALCULATE(
    customer_name=customer_name
)

least_common_color_description = ref_color.CALCULATE(
    color_description_name=color_description,
    product_count=COUNT(product.product_id)
).ORDER_BY(
    product_count.ASC()
).TOP_K(1).CALCULATE(
    color_description=color_description_name
)

most_papers_institution = insts.CALCULATE(
    inst_name=name,
    num_papers=COUNT(authorships)
).TOP_K(1, by=num_papers.DESC()).CALCULATE(
    inst_name=inst_name
)

employee_163_salary = employee.WHERE(EMPLOYEE_ID == 163).SINGULAR().SALARY + 0

employees_earning_more = employee.WHERE(
    SALARY + 0 > employee_163_salary
).CALCULATE(
    full_name=JOIN_STRINGS(' ', FIRST_NAME, LAST_NAME)
)

female_students_by_major = students.WHERE(
    sex == 'F'
).PARTITION(
    name="majors",
    by=major
).CALCULATE(
    major=major,
    num_female_students=COUNT(students)
).TOP_K(1, by=num_female_students.DESC()).CALCULATE(
    major=major,
    num_female_students=num_female_students
)

average_age_of_students_with_food_and_animal_allergies = students.WHERE(
    (HAS(has_allergies.allergy_type.WHERE(AllergyType == 'food')) == 1) &
    (HAS(has_allergies.allergy_type.WHERE(AllergyType == 'animal')) == 1)
).CALCULATE(
    average_age=AVG(age)
)

scholarship_sports = sportsinfos.WHERE(
    onscholarship == 'yes'
).PARTITION(
    name="sports",
    by=sportname
).CALCULATE(
    sport_name=sportname,
    scholarship_student_count=COUNT(sportsinfos.stuid)
).TOP_K(1, by=scholarship_student_count.DESC()).CALCULATE(
    sport_name,
    scholarship_student_count
)

media_type_track_info = tracks.CALCULATE(
    mediatype_name=mediatype.name
)

least_common_media_type = media_type_track_info.PARTITION(
    name="media_types_group",
    by=mediatype_name
).CALCULATE(
    mediatype_name=mediatype_name,
    num_tracks=COUNT(tracks)
).TOP_K(1, by=num_tracks.ASC()).CALCULATE(
    least_common_mediatype=mediatype_name
)

enrollments_with_dept = enrolls.CALCULATE(
    enroll_dept_name=clas.course.department.dept_name
)

department_enrollment_counts = enrollments_with_dept.PARTITION(
    name="departments_group", by=enroll_dept_name
).CALCULATE(
    dept_name=enroll_dept_name,
    num_students_enrolled=COUNT(enrollments_with_dept)
)

department_with_most_students = department_enrollment_counts.TOP_K(
    1, by=num_students_enrolled.DESC()
).CALCULATE(
    dept_name=dept_name
)
